//! Deterministic fuzz tests for the ClientHello parser.
//!
//! The L4 listener feeds attacker-controlled bytes into [`parse_client_hello`] on every connection,
//! so the parser must never panic, never hang, and only ever return a typed [`ParseError`] or a
//! classification. The corpus is generated by a fixed xorshift PRNG so failures are reproducible:
//! 10 000+ random buffers, 10 000+ mutated valid ClientHellos, and oversized declared lengths.

use caddy_rs_l4::{parse_client_hello, ParseError};

/// xorshift64 — deterministic, dependency-free PRNG.
fn xorshift(state: &mut u64) -> u64 {
    let mut x = *state;
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    *state = x;
    x
}

/// Builds a complete TLS record containing a ClientHello with the given SNI/ALPN extensions.
fn client_hello(sni: Option<&str>, alpn: &[&str]) -> Vec<u8> {
    let mut extensions = Vec::new();
    if let Some(host) = sni {
        let mut names = vec![0_u8];
        names.extend_from_slice(&(host.len() as u16).to_be_bytes());
        names.extend_from_slice(host.as_bytes());
        let mut ext = Vec::new();
        ext.extend_from_slice(&(names.len() as u16).to_be_bytes());
        ext.extend_from_slice(&names);
        extensions.extend_from_slice(&0x0000_u16.to_be_bytes());
        extensions.extend_from_slice(&(ext.len() as u16).to_be_bytes());
        extensions.extend_from_slice(&ext);
    }
    if !alpn.is_empty() {
        let mut protocols = Vec::new();
        for name in alpn {
            protocols.push(name.len() as u8);
            protocols.extend_from_slice(name.as_bytes());
        }
        let mut ext = Vec::new();
        ext.extend_from_slice(&(protocols.len() as u16).to_be_bytes());
        ext.extend_from_slice(&protocols);
        extensions.extend_from_slice(&0x0010_u16.to_be_bytes());
        extensions.extend_from_slice(&(ext.len() as u16).to_be_bytes());
        extensions.extend_from_slice(&ext);
    }
    let mut body = Vec::new();
    body.extend_from_slice(&[0x03, 0x03]);
    body.extend_from_slice(&[0x11; 32]);
    body.push(0);
    body.extend_from_slice(&[0x00, 0x02, 0x13, 0x01]);
    body.extend_from_slice(&[1, 0]);
    if !extensions.is_empty() {
        body.extend_from_slice(&(extensions.len() as u16).to_be_bytes());
        body.extend_from_slice(&extensions);
    }
    let mut handshake = vec![1_u8];
    handshake.extend_from_slice(&(body.len() as u32).to_be_bytes()[1..]);
    handshake.extend_from_slice(&body);
    let mut record = vec![0x16_u8];
    record.extend_from_slice(&[0x03, 0x01]);
    record.extend_from_slice(&(handshake.len() as u16).to_be_bytes());
    record.extend_from_slice(&handshake);
    record
}

#[test]
fn random_buffers_never_panic_and_only_return_typed_errors() {
    let mut state = 0x9e37_79b9_7f4a_7c15_u64;
    let mut errors = 0_u32;
    for _ in 0..12_000 {
        let len = (xorshift(&mut state) % 700) as usize;
        let mut buf = Vec::with_capacity(len);
        for _ in 0..len {
            buf.push(xorshift(&mut state) as u8);
        }
        // Half the buffers start like a TLS record so the deeper record/handshake/extensions
        // parsers are exercised rather than only the protocol sniff.
        if len >= 5 && xorshift(&mut state) & 1 == 0 {
            buf[0] = 0x16;
        }
        match parse_client_hello(&buf) {
            // A random buffer may coincidentally classify as another protocol; the contract is
            // only that it never panics and never silently claims TLS without parsing one.
            Ok(_) => {}
            Err(error) => {
                errors += 1;
                assert!(!error.to_string().is_empty());
            }
        }
    }
    assert!(
        errors > 9_000,
        "most random buffers must be typed errors, got {errors}"
    );
}

#[test]
fn mutated_valid_client_hellos_never_panic() {
    let valid = client_hello(Some("fuzz.example"), &["h2", "http/1.1"]);
    let mut state = 0x0123_4567_89ab_cdef_u64;
    let mut errors = 0_u32;
    for _ in 0..12_000 {
        let mut buf = valid.clone();
        let mutations = 1 + (xorshift(&mut state) % 4) as usize;
        for _ in 0..mutations {
            let index = (xorshift(&mut state) as usize) % buf.len();
            buf[index] = xorshift(&mut state) as u8;
        }
        match parse_client_hello(&buf) {
            // A mutation can still leave a parseable record; the contract is no panic and only
            // typed errors otherwise.
            Ok(_) => {}
            Err(error) => {
                errors += 1;
                assert!(!error.to_string().is_empty());
            }
        }
    }
    assert!(errors > 0, "mutations must produce some typed errors");
}

#[test]
fn oversized_declared_lengths_are_typed_errors_not_panics() {
    // Record length says 65535 bytes but the buffer holds far fewer: retryable.
    let mut record_len = client_hello(Some("x.example"), &["h2"]);
    record_len[3..5].copy_from_slice(&[0xff, 0xff]);
    assert_eq!(parse_client_hello(&record_len), Err(ParseError::Incomplete));

    // Handshake length (u24) says 16777215 bytes: still retryable, not a panic.
    let mut handshake_len = client_hello(Some("x.example"), &["h2"]);
    handshake_len[6..9].copy_from_slice(&[0xff, 0xff, 0xff]);
    assert_eq!(
        parse_client_hello(&handshake_len),
        Err(ParseError::Incomplete)
    );

    // A complete record whose extensions block claims 65535 bytes: permanent typed rejection.
    // Body layout: version(2) random(32) session_id_len(1)+session(0) cipher_len(2) suites(2)
    // compression_len(1) compression(1) => extensions_len starts at record(5)+hs(4)+41 = 50.
    let mut extensions_len = client_hello(Some("x.example"), &[]);
    let offset = 50;
    extensions_len[offset..offset + 2].copy_from_slice(&[0xff, 0xff]);
    assert!(matches!(
        parse_client_hello(&extensions_len),
        Err(ParseError::Malformed(_))
    ));

    // Truncated to the record header with a zero content type: typed error, no panic.
    assert_eq!(
        parse_client_hello(&[0x00, 0x03, 0x01, 0x00, 0x00]),
        Err(ParseError::BadRecordContentType(0x00))
    );
}
